import type { Metadata } from "next";

import { siteConfig } from "@/config/site";

interface SocialMetadataOptions {
  title: string;
  description: string;
  /** Path of the page, resolved against `metadataBase`. */
  path: string;
}

/**
 * `openGraph` and `twitter` for a static page.
 *
 * Nested metadata objects are merged shallowly: a page that sets `openGraph`
 * replaces the root one entirely, including the image generated by
 * `src/app/opengraph-image.tsx`. This helper restates the shared fields and
 * points back at that image, so every page keeps a social card.
 */
export function socialMetadata({
  title,
  description,
  path,
}: SocialMetadataOptions): Pick<Metadata, "openGraph" | "twitter"> {
  const images = [
    { url: siteConfig.ogImage, width: 1200, height: 630, alt: siteConfig.name },
  ];

  return {
    openGraph: {
      type: "website",
      siteName: siteConfig.name,
      title,
      description,
      url: path,
      images,
    },
    twitter: { card: "summary_large_image", title, description, images },
  };
}
